    fld=await pg.evaluate("(()=>{const el=[...document.querySelectorAll('#app input[data-k]')].find(e=>e.type==='text'||e.type===''||e.type==='search'); return el && el.dataset.k})()")
    if fld:
        n0=await pg.evaluate("(state.editLog||[]).length"); before=await pg.evaluate(f"g('{fld}')")
        sel=f'#app input[data-k="{fld}"]'; await pg.fill(sel,'blocked edit (test)'); await pg.wait_for_timeout(150)
        chk('edits blocked until a technician name is set', await pg.evaluate("(state.editLog||[]).length")==n0 and await pg.evaluate(f"g('{fld}')")==before, fld)
    else: chk('edits blocked until a technician name is set (field found)', False)
    await pg.evaluate("sessionStorage.removeItem('mfr-technician'); window.prompt=()=>''")
    r0=await pg.evaluate("(()=>{const m=state.modules.find(x=>x.type==='det'); m.typical={'cfg.alert':true}; const n0=(state.editLog||[]).length; const r=confirmTypical(m); return [r, (state.editLog||[]).length-n0, Object.keys(m.typical||{}).length]})()")
    chk('Confirm typical values blocked without a technician name', r0==[0,0,1], r0)
    await pg.evaluate("window.prompt=()=>'Pat Field'")
    r1=await pg.evaluate("(()=>{const m=state.modules.find(x=>x.type==='det'); const r=confirmTypical(m); const e=state.editLog[state.editLog.length-1]; return [r, e.by, e.kind]})()")
    chk('Confirm typical asks for the name, then logs it', r1==[1,'Pat Field','confirm-typical'], r1)
    await pg.evaluate("sessionStorage.removeItem('mfr-technician'); window.prompt=()=>''")
    blk=await pg.evaluate("(()=>{const b=document.createElement('button'); b.dataset.act='stopwatch'; document.body.appendChild(b); let hit=false; const h=()=>{hit=true}; document.addEventListener('click',h); b.click(); document.removeEventListener('click',h); b.remove(); return hit})()")
    chk('stopwatch/photo/import actions blocked without a name', blk is False, blk)
    await pg.evaluate("sessionStorage.setItem('mfr-technician','Pat Field')")
    i=await pg.evaluate("state.modules.findIndex(m=>m.design && m.design['cfg.fan'])")
    dv=await pg.evaluate(f"state.modules[{i}].design['cfg.fan']")
    nv=str(int(dv)+1)
    await pg.evaluate(f"s('modules.{i}.cfg.fan','{nv}')"); await pg.evaluate(f"s('modules.{i}.cfg.fan','{int(nv)+1}')")
    log=await pg.evaluate("state.editLog")
    chk('edit log entry has who/when/old/new', log and log[-1]['by']=='Pat Field' and log[-1]['old']==nv and log[-1]['new']==str(int(nv)+1) and log[-1]['at'], log[-1] if log else None)
    chk('edit log never overwrites: two quick edits = two entries', len(log)>=2 and log[-2]['old']==dv and log[-2]['new']==nv and log[-2]['n']+1==log[-1]['n'], log[-2:])
    ch=await pg.evaluate(f"state.changes.filter(c=>c.status==='logged')")
    chk('field change logged against design value', len(ch)==1 and ch[0]['design']==dv and ch[0]['value']==str(int(nv)+1) and ch[0]['pipecad'], ch)
    j=await pg.evaluate("state.modules.findIndex(m=>m.type==='det')")
    await pg.evaluate(f"(()=>{{const m=state.modules[{j}]; m.perf.target=m.perf.target||'EWFD'; Object.keys(m.cfg).forEach(k=>{{}}); m.typical={{'cfg.alert':true,'cfg.action':true}}; confirmTypical(m);}})()")
    c=await pg.evaluate("state.editLog.filter(e=>e.kind==='confirm-typical')")
    chk('typical confirmation logged with who/keys', c and c[-1]['by']=='Pat Field' and 'cfg.alert' in c[-1]['keys'], c)
    await pg.evaluate("openFieldChanges()"); await pg.screenshot(path=SH+'rpt-field-changes-dialog.png')
    await pg.fill('#fcTech','Pat Field'); await pg.click('#fcSign'); await pg.screenshot(path=SH+'rpt-field-changes-signed.png')
    async with pg.expect_download() as d: await pg.evaluate('saveProject()')
    v=await d.value; pth=OUT+'out.mlproj.json'; await v.save_as(pth); o=json.load(open(pth))
    chk('Save keeps imported field change (verified)', any(x['id']=='fc-qa-1' and x['status']=='verified' for x in o.get('changes',[])))
    chk('Save keeps new logged change', any(x['status']=='logged' for x in o.get('changes',[])))
    chk('Save keeps designer approval', o.get('approvals',{}).get('designer',{}).get('name')=='Designer')
    chk('technician sign-off stored', o['approvals'].get('technician',{}).get('name')=='Pat Field')
    chk('unknown top-level key kept', o.get('futureKey')=={'keep':'me'})
    chk('savedBy has the user name', o['savedBy'].get('name')=='Pat Field', o['savedBy'])
    chk('design hash is SHA-256', o['design']['hash'].startswith('sha256:') and len(o['design']['hash'])==71, o['design']['hash'])
    chk('Save keeps Performance Criteria (EOR, spec, narrative)', o['design'].get('performance',{}).get('eorName')=='J. Engineer, PE' and o['design']['performance'].get('specRef')=='Section 28 31 00, 2.4.B' and 'QA narrative' in o['design']['performance'].get('narrative',''))
    txt=await pg.evaluate("JSON.stringify(buildBlocks({}))")
    chk('Report summary prints UL statement, referenced standard, code prescriptions, area override, EOR, spec ref and narrative', all(k in txt for k in ['Complies with UL 268, 7th Edition','Referenced standard: VEWFD – NFPA 76/318','NFPA 76-2024 8.5.3.1.2.5','Override: Zone FM','SFD – FM DS 5-48','J. Engineer, PE','Section 28 31 00','QA narrative','2.18']), '')
    lim=await pg.evaluate("limits(state.modules.find(m=>m.type==='det'))")
    chk('Report limits use project Performance Criteria', lim is not None, lim)
    fz=await pg.evaluate("(()=>{const m=JSON.parse(JSON.stringify(state.modules.find(x=>x.type==='det'))); m.area='Zone FM'; m.perf=Object.assign({},m.perf,{target:'SFD',cSens:'',cTime:''}); return limits(m).sens})()")
    unc=await pg.evaluate("(()=>{state.design.performance.ulConfirmed=false; const t=JSON.stringify(buildBlocks({})); state.design.performance.ulConfirmed=true; return t})()")
    chk('Report withholds the UL 268 statement when not confirmed by the engineer', 'Complies with UL 268' not in unc and 'NOT YET CONFIRMED' in unc)
    chk('Report checks a module against its Area/Group override (FM SFD 2.5)', fz==2.5, fz)
    ev=lambda holes: pg.evaluate("(h=>{const m=JSON.parse(JSON.stringify(state.modules.find(x=>x.type==='det'))); m.area=''; m.perf=Object.assign({},m.perf,{target:'VEWFD',cSens:'',cTime:''}); m.pipecad={holes:h}; const r=evalModule(m); const f=l=>(r.it.find(x=>x.label===l)||{}).st; return [f('PipeCAD worst-hole sensitivity'), f('PipeCAD most-sensitive hole vs UL lower limit'), f('PipeCAD fastest hole vs UL lower limit')]})", holes)
    e1=await ev([{'i':1,'sens':1.0,'tt':60},{'i':2,'sens':0.5,'tt':20}])
    chk('≤ rule: a VEWFD hole exactly at 1.00 %obs/ft and 60 s passes (Brent 2026-10-13)', e1==['P','P','P'], e1)
    e2=await ev([{'i':1,'sens':1.01,'tt':30}])
    chk('VEWFD hole at 1.01 fails', e2[0]=='F', e2)
    e3=await ev([{'i':1,'sens':0.9,'tt':30},{'i':2,'sens':0.03,'tt':2}])
    chk('UL project: hole below the Range 1 lower limits (0.05 %obs/ft, 3 s) fails', e3[1]=='F' and e3[2]=='F', e3)
    n3=await pg.evaluate("(()=>{const m=JSON.parse(JSON.stringify(state.modules.find(x=>x.type==='det'))); m.area=''; m.perf=Object.assign({},m.perf,{target:'VEWFD',cSens:'',cTime:''}); m.pipecad={holes:[{i:1,sens:0.9,tt:30},{i:2,sens:0.03,tt:2}]}; return evalModule(m).it.filter(x=>/vs UL lower limit/.test(x.label)).map(x=>x.note)})()")
    chk('lower-bound FAIL reads "Outside UL 268 listed range"', len(n3)==2 and all('Outside UL 268 listed range' in x for x in n3), n3)
    tx=await pg.evaluate("JSON.stringify(buildBlocks({}))")
    chk('Report prints Target values and UL ranges ', all(k in tx for k in ['Target (%obs/ft)','1.0','1.5','2.0','Special Application Range 1','Open Area: 1.70–2.18','≤1']) and 'PROVISIONAL' not in tx and all(k in tx for k in ['≤1']) and 'strictly less than' not in tx, '')
    await pg.evaluate("state.ui.view='sec:A'; renderAll()"); await pg.wait_for_timeout(200)
    el=await pg.query_selector('#perf-criteria')
